            if s[i].isspace():
                i += 1
            elif s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(('NUM', int(s[i:j])))
                i = j
            elif s[i] in '+-*/()':
                tokens.append((s[i], s[i]))
                i += 1
            else:
                i += 1
        return tokens

    tokens = tokenize(expr)
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        token = peek()
        pos[0] += 1
        return token

    def parse_expr():
        left = parse_term()
        while peek() and peek()[0] in ('+', '-'):
            op = consume()[0]
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        left = parse_factor()
        while peek() and peek()[0] in ('*', '/'):
            op = consume()[0]
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                left = int(left / right)
        return left

    def parse_factor():
        token = peek()
        if token and token[0] == '-':
            consume()
            return -parse_factor()
        elif token and token[0] == '+':
            consume()
            return parse_factor()
        elif token and token[0] == '(':
            consume()
            result = parse_expr()
            consume()
            return result
        elif token and token[0] == 'NUM':
            return consume()[1]
        return 0

    return parse_expr()

